data.setupCode:
// 128 point slots (the Points param decides how many are alive). World units:
// y in -0.5..0.5 (screen height = 1), x scaled by the screen aspect.
const N = 128, MAXL = 192;
state.N = N;
state.MAXL = MAXL;
state.p = new Float32Array(N * 2);     // positions
state.v = new Float32Array(N * 2);     // velocities
state.hue = new Float32Array(N);       // 0..1 along the Colour A -> B gradient
for (let i = 0; i < N; i++) {
  const a = Math.random() * Math.PI * 2, r = 0.05 + Math.random() * 0.35;
  state.p[2 * i] = Math.cos(a) * r;
  state.p[2 * i + 1] = Math.sin(a) * r * 0.7;
  state.hue[i] = Math.random();
}
// Data textures for the shader:
//   points: N x 1 texels  (x, y, speed, hue)
//   links:  MAXL x 2 texels, row 0 = (x1, y1, x2, y2), row 1 = (strength, hue1, hue2, 0)
state.pts = new Float32Array(N * 4);
state.links = new Float32Array(MAXL * 2 * 4);
state.hot = 0;

data.code:
// Orbital swarm: every point is pulled by one of a few attractors drifting on slow
// Lissajous paths, with a sideways swirl (so it orbits), short-range separation and
// drag. The mouse attracts or repels while it moves. Integration is semi-implicit
// Euler in fixed 1/120 s sub-steps, so the motion is the same at any frame rate.
const { N, MAXL, p, v, hue, pts, links } = state;
const n = clamp(Math.round(params['Points'] ?? 96), 2, N);
const A = clamp(Math.round(params['Attractors'] ?? 3), 1, 4);
const speed = params['Speed'] ?? 1;
const swirl = params['Swirl'] ?? 1;
const R = params['Link distance'] ?? 0.2;
const mode = params['Mouse'] | 0;              // 0 attract, 1 repel, 2 off
const burst = (params['Kick burst'] ?? 1) * audio.kick;
const aspect = resolution[0] / Math.max(1, resolution[1]);
const W = 0.5 * aspect - 0.04, H = 0.46;

// Attractors
const att = [];
for (let k = 0; k < A; k++) {
  const t = time * 0.21 * speed + k * 2.4;
  att.push([W * 0.7 * Math.sin(t * 1.3 + k * 1.7), H * 0.7 * Math.sin(t * 1.9 + k * 0.9)]);
}

// The mouse counts while it moves, then fades out over ~2 s
const mx = (mouse[0] - 0.5) * aspect, my = mouse[1] - 0.5;
const moved = state.mx !== undefined && Math.hypot(mx - state.mx, my - state.my) > 1e-4;
state.mx = mx; state.my = my;
state.hot = moved ? 1 : Math.max(0, state.hot - dt / 2);
const hot = mode === 2 ? 0 : state.hot;

const steps = Math.min(8, Math.max(1, Math.ceil(dt / (1 / 120))));
const h = (dt / steps) * speed;
const drag = Math.exp(-2.5 * h);
for (let s = 0; s < steps; s++) {
  for (let i = 0; i < n; i++) {
    const x = p[2 * i], y = p[2 * i + 1];
    const [cx, cy] = att[i % A];
    const dx = cx - x, dy = cy - y;
    const d = Math.hypot(dx, dy) + 1e-4;
    // spring toward the attractor + a constant sideways push: with the drag this settles
    // into orbits of radius ~ 0.2 x Swirl around each attractor
    let ax = 8.0 * dx - swirl * 1.4 * dy / d;
    let ay = 8.0 * dy + swirl * 1.4 * dx / d;
    // kick: a burst away from the attractor
    ax -= burst * 6 * dx / d;
    ay -= burst * 6 * dy / d;
    // mouse
    if (hot > 0) {
      const ex = mx - x, ey = my - y, e2 = ex * ex + ey * ey;
      const f = hot * (mode === 0 ? 5 / (1 + 30 * e2) : -1.2 * Math.exp(-e2 * 60) / Math.sqrt(e2 + 1e-4));
      ax += f * ex;
      ay += f * ey;
    }
    // separation from close neighbours
    for (let j = 0; j < n; j++) {
      if (j === i) continue;
      const qx = x - p[2 * j], qy = y - p[2 * j + 1], q2 = qx * qx + qy * qy;
      if (q2 < 0.0016 && q2 > 1e-10) {
        const f = (0.0016 - q2) / 0.0016 * 12 / Math.sqrt(q2);
        ax += qx * f;
        ay += qy * f;
      }
    }
    // soft walls
    if (x > W) ax -= (x - W) * 40; else if (x < -W) ax -= (x + W) * 40;
    if (y > H) ay -= (y - H) * 40; else if (y < -H) ay -= (y + H) * 40;
    v[2 * i] = v[2 * i] * drag + ax * h;
    v[2 * i + 1] = v[2 * i + 1] * drag + ay * h;
    const sp = Math.hypot(v[2 * i], v[2 * i + 1]);
    if (sp > 1.5) { v[2 * i] *= 1.5 / sp; v[2 * i + 1] *= 1.5 / sp; }
  }
  for (let i = 0; i < n; i++) {
    p[2 * i] += v[2 * i] * h;
    p[2 * i + 1] += v[2 * i + 1] * h;
  }
}

// Points texture
for (let i = 0; i < N; i++) {
  pts[4 * i] = p[2 * i];
  pts[4 * i + 1] = p[2 * i + 1];
  pts[4 * i + 2] = Math.hypot(v[2 * i], v[2 * i + 1]);
  pts[4 * i + 3] = hue[i];
}
// Links between near points (strongest when close), up to MAXL
let L = 0;
for (let i = 0; i < n && L < MAXL; i++) {
  for (let j = i + 1; j < n && L < MAXL; j++) {
    const dx = p[2 * j] - p[2 * i], dy = p[2 * j + 1] - p[2 * i + 1];
    const d = Math.hypot(dx, dy);
    if (d < R) {
      links.set([p[2 * i], p[2 * i + 1], p[2 * j], p[2 * j + 1]], 4 * L);
      links.set([1 - d / R, hue[i], hue[j], 0], 4 * (MAXL + L));
      L++;
    }
  }
}
return {
  points: dataTexture(pts, N, 1, 4),
  links: dataTexture(links, MAXL, 2, 4),
  count: float(n),
  linkCount: float(L),
};

SwarmField.customGLSL:
// @node swarmField
// @title Swarm Field
// @category custom
// @description Renders the JS swarm: points (N x 1 data texture: x, y, speed, hue) as glowing metaballs with a bright iso rim, and links (MAXL x 2: row 0 = x1 y1 x2 y2, row 1 = strength hue1 hue2) as glowing lines. Coordinates: y in -0.5..0.5, x scaled by the aspect. Keeps max(new, last frame x trails) from prev (a Feedback of its own output). Returns HDR color.
vec3 sf_col(vec3 a, vec3 b, float t) {
    return mix(a, b, smoothstep(0.0, 1.0, t));
}

vec3 swarmField(vec2 uv, sampler2D points, sampler2D links, float count, float linkCount, sampler2D prev, float blobSize, float glow, float trails, vec3 colorA, vec3 colorB) {
    float aspect = u_resolution.x / max(u_resolution.y, 1.0);
    vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
    float field = 0.0;
    float wsum = 0.0;
    vec3 tint = vec3(0.0);
    vec3 halo = vec3(0.0);
    float r0 = blobSize * blobSize;
    for (int i = 0; i < 128; i++) {
        if (float(i) >= count) break;
        vec4 q = texelFetch(points, ivec2(i, 0), 0);
        vec2 d = p - q.xy;
        float r2 = dot(d, d);
        // Compact metaball kernel (1 - r²/R²)³ with R = 2.2 x blob size: blobs only merge when close
        float k = max(1.0 - r2 / (r0 * 4.84), 0.0);
        float f = k * k * k * 2.0;
        vec3 c = sf_col(colorA, colorB, q.w) * (1.0 + 0.6 * clamp(q.z, 0.0, 1.5));
        field += f;
        tint += c * f;
        wsum += f;
        halo += c * r0 * 0.12 / (r2 + r0 * 0.6);
    }
    vec3 lines = vec3(0.0);
    for (int i = 0; i < 192; i++) {
        if (float(i) >= linkCount) break;
        vec4 e = texelFetch(links, ivec2(i, 0), 0);
        vec4 m = texelFetch(links, ivec2(i, 1), 0);
        vec2 pa = p - e.xy;
        vec2 ba = e.zw - e.xy;
        float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-8), 0.0, 1.0);
        float dl = length(pa - ba * h);
        vec3 c = mix(sf_col(colorA, colorB, m.y), sf_col(colorA, colorB, m.z), h);
        float core = 1.0 - smoothstep(0.0, 0.002, dl);
        lines += c * m.x * (core * 0.8 + 0.00002 / (dl * dl + 0.00002) * 0.6);
    }
    vec3 base = tint / max(wsum, 1e-6);
    float aa = fwidth(field) + 1e-4;
    float body = smoothstep(1.0 - aa, 1.0 + aa, field);
    float rim = exp(-abs(field - 1.0) * 4.0) * step(0.02, field);
    // Background: deep blue-black with a soft vertical gradient
    vec3 col = mix(vec3(0.006, 0.008, 0.02), vec3(0.02, 0.012, 0.04), uv.y);
    col += lines * glow;
    col += halo * glow;
    col += base * (body * (0.3 + 0.2 * min(field, 4.0)) + rim * 0.9) * glow;
    col += vec3(1.0) * body * smoothstep(2.5, 6.0, field) * 0.35;   // white-hot cores where blobs merge
    // Trails
    vec2 pu = uv;
    vec3 old = texture(prev, pu).rgb * trails;
    return max(col, old);
}
